    """
    if proc := subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE if varargs else subprocess.DEVNULL, text=True, encoding='utf-8', shell=True, start_new_session=True if color else False):
