decorator_cache = {}
def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """

    if key not in decorator_cache:
        decorator_cache[key] = {
            'func': (lambda f: f.__name__)(f),
            'results': {},
            'lock': lock
        }

    def inner(*args, **kwargs):
        if decorator_cache[key]['lock']:
            decorator_cache[key]['lock'].acquire()
        try:
            if args not in decorator_cache[key]['results']:
                decorator_cache[key]['results'][args] = decorator_cache[key]['func'](*args, **kwargs)
            return decorator_cache[key]['results'][args]
        finally:
            if decorator_cache[key]['lock']:
                decorator_cache[key]['lock'].release()

    return inner

