def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if isinstance(e, BaseException):
        exc = {'type': type(e).__name__, 'message': str(e)}
        if len(e.args) > 0:
            exc['message'] += ', args=' + ', '.join(map(str, e.args))
        if e.__traceback__:
            traceback = e.__traceback__
            frame = traceback.pop()
            if frame:
                exc['frames'] = [{'filename': frame.filename, 'line': frame.lineno}]
                if frame.f_back:
                    exc['frames'].append({'filename': frame.f_back.filename, 'line': frame.f_back.lineno})
                while len(exc['frames']) < max_path_level:
                    exc['frames'].insert(0, {'filename': frame.filename, 'line': frame.lineno})
                    stack = traceback.pop()
                    if stack is not None:
                        frame = stack.f_back
                        if frame is not None:
                            exc['frames'].insert(0, {'filename': frame.filename, 'line': frame.lineno})
                        else:
                            break
            if len(exc['frames']) > max_path_level:
                exc['frames'] = exc['frames'][:max_path_level]
        if traceback:
            exc['additional traces'] = []
            while traceback:
                traceback.pop()
        if len(exc['additional traces']) > max_path_level:
            exc['additional traces'] = exc['additional traces'][:max_path_level]
        return exc
    else:
        raise TypeError('extostr() takes one argument only')
