def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    output = ' ' * indent + self.__class__.__name__ + '\n'
    if debug:
        output += ' ' * indent + '\tDEBUG: ' + str(self.debug) + '\n'
    if self.content:
        if isinstance(self.content, SelfReferenceElement):
            if self.reference:
                output += ' ' * (indent + 1) + 'Content: <ref ' + str(self.reference) + '>\n'
            else:
                output += ' ' * (indent + 1) + 'Content: None\n'
        else:
            output += ' ' * (indent + 1) + 'Content: ' + self.content.__class__.__name__ + '\n'
            if debug and hasattr(self.content, 'debug'):
                output += ' ' * (indent + 2) + '\tDEBUG: ' + str(self.content.debug) + '\n'
            output += self.content.pretty(indent + 2, debug)
    if self.children:
        for child in self.children:
            output += child.pretty(indent + 2, debug)
    return output
