import os
from git import Repo, InvalidGitRepositoryError
from typing import List, Optional
from .models import Inventory, FileDigest

def validate_version_inventories(self, version_dirs: List[str]) -> None:
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory = Inventory()
    differences = []

    for version_dir in version_dirs:
        repo = Repo(version_dir)
        if not repo:
            raise InvalidGitRepositoryError(f"No Git repository found in {version_dir}")

        # Check if the repository matches the root inventory's configuration
        try:
            with open(os.path.join(repo.working_dir, "config"), "r") as f:
                for line in f:
                    if "root" in line:
                        break
        except FileNotFoundError:
            raise FileNotFoundError(f"No configuration file found in {version_dir}")

        # Check if the repository has an inventory
        try:
            inventory = next(repo.inventory)
        except StopIteration:
            raise NoInventoryError(f"No inventory found in {version_dir}")

        # Compare the inventory with the root inventory
        if not inventory.equals(root_inventory):
            differences.append((version_dir, inventory))

        # Check if the repository has any content digests different from those in the root inventory
        try:
            with open(os.path.join(repo.working_dir, "README.md"), "r") as f:
                # Extract the content digest from the README.md
                digest = f.read().split("\n")[11].split(":")[1].strip()
            if digest != self.root_inventory.digest:
                differences.append((version_dir, Inventory(digest=digest)))
        except FileNotFoundError:
            pass

    if differences:
        raise InventoryMismatchError("Version inventories are mismatched for the following repositories:\n" + "\n".join([f"{dir}: {diff}" for dir, diff in differences]))
    else:
        print("Version inventories are correctly configured and consistent.")
