def deep_merge_nodes(nodes):
    def merge(node1, node2):
        if isinstance(node1, dict) and isinstance(node2, dict):
            return {**node1, **node2}
        elif isinstance(node1, list) and isinstance(node2, list):
            return node1 + node2
        else:
            return node2

    result = {}
    for key in {k[0] for k, v in nodes if k[0] not in result}:
        result[key] = merge(next((k, v) for k, v in nodes if k[0] == key), next((k, v) for k, v in nodes if k[1] == key))

    return list(result.items())
