def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    unit = frequency[-1]
    value = int(frequency[:-1])

    if unit == 's':
        return timedelta(seconds=value)
    elif unit == 'm':
        return timedelta(minutes=value)
    elif unit == 'h':
        return timedelta(hours=value)
    elif unit == 'd':
        return timedelta(days=value)
    elif unit == 'w':
        return timedelta(weeks=value)
    elif unit in ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']:
        # handle weekly frequency
        if value >= 7:
            raise ValueError("Weekly frequency must be less than 7 days. Given: {0}".format(frequency))
        return timedelta(days=7 * (value + 1) // 7 - (value + 1) % 7)
    else:
        raise ValueError("Invalid frequency format. Given: {0}".format(frequency))
