    required_when_conditions = {}
    replacement_args = {}
    replacement_value = None

    for option in options_spec:
        if "required_when" in option:
            match_arg_name = option["required_when"]["arg"]
            if match_arg_name in args and args[match_arg_name]:
                replacement_value = option["required_when"]["value"]
            required_when_conditions[match_arg_name] = replacement_value

